// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 burnValue) public {
        vm.assume(burnValue <= c.balanceOf(address(this)));
        c.mintToken(address(this), burnValue);

        c.owned();

        address ownerBefore = c.owner();

        c.burn(burnValue);

        assertTrue(c.owner() == ownerBefore);
    }
}
